**server.js** — Core auth system
```javascript
import express from 'express';
import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';
import rateLimit from 'express-rate-limit';

const app = express();
app.use(express.json());

const SECRET_KEY = process.env.SECRET_KEY || 'dev-secret-key';
const users = new Map(); // email -> { hashedPassword, createdAt }
const failedAttempts = new Map(); // ip -> [timestamps]
const sessions = new Map(); // token -> { userId, expiresAt }

// Rate limiter: 5 failed attempts per 15 min per IP
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  keyGenerator: (req) => req.ip,
  handler: (req, res) => res.status(429).json({ error: 'Too many login attempts, try again later' }),
  skip: (req) => !req.body.email, // Only count if email provided
});

app.post('/signup', async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) return res.status(400).json({ error: 'Email and password required' });
    if (users.has(email)) return res.status(409).json({ error: 'Email already exists' });
    if (password.length < 8) return res.status(400).json({ error: 'Password must be 8+ characters' });

    const hashedPassword = await bcrypt.hash(password, 10);
    users.set(email, { hashedPassword, createdAt: new Date() });

    res.status(201).json({ message: 'Signup successful' });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/login', loginLimiter, async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) return res.status(400).json({ error: 'Email and password required' });

    const user = users.get(email);
    if (!user || !(await bcrypt.compare(password, user.hashedPassword))) {
      return res.status(401).json({ error: 'Invalid email or password' });
    }

    const token = jwt.sign({ email }, SECRET_KEY, { expiresIn: '24h' });
    sessions.set(token, { email, expiresAt: Date.now() + 24 * 60 * 60 * 1000 });

    res.json({ token, expiresIn: '24h' });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

const verifyToken = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });

  try {
    const decoded = jwt.verify(token, SECRET_KEY);
    const session = sessions.get(token);
    if (!session || session.expiresAt < Date.now()) {
      sessions.delete(token);
      return res.status(401).json({ error: 'Token expired' });
    }
    req.user = decoded;
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid token' });
  }
};

app.get('/protected', verifyToken, (req, res) => {
  res.json({ message: `Hello ${req.user.email}` });
});

app.post('/logout', verifyToken, (req, res) => {
  const token = req.headers.authorization.split(' ')[1];
  sessions.delete(token);
  res.json({ message: 'Logged out' });
});

app.listen(3000, () => console.log('Server running on http://localhost:3000'));
```

**test.sh** — Quick test commands
```bash
#!/bin/bash

BASE="http://localhost:3000"

# Signup
echo "=== SIGNUP ==="
curl -X POST $BASE/signup \
  -H "Content-Type: application/json" \
  -d '{"email":"user@example.com","password":"password123"}'

# Login
echo -e "\n=== LOGIN ==="
TOKEN=$(curl -s -X POST $BASE/login \
  -H "Content-Type: application/json" \
  -d '{"email":"user@example.com","password":"password123"}' | jq -r '.token')

echo "Token: $TOKEN"

# Access protected route
echo -e "\n=== PROTECTED ROUTE ==="
curl -X GET $BASE/protected \
  -H "Authorization: Bearer $TOKEN"

# Logout
echo -e "\n=== LOGOUT ==="
curl -X POST $BASE/logout \
  -H "Authorization: Bearer $TOKEN"
```

**Key features:**
- **Signup:** Email validation, 8+ char password, bcrypt hashing (10 rounds)
- **Login:** Rate limited (5 attempts per 15 min per IP), JWT tokens with 24h expiry
- **Sessions:** In-memory session tracking, token validation on protected routes
- **Logout:** Blacklist tokens by deleting from session store

Run with `npm install && npm start`, then test with `bash test.sh`.
